<template>
  <main class="qva-page"><header class="qva-hero"><div><span>QGAUSS / MOTION CONTROL</span><h1>让创意，<br>拥有自己的片场<em>。</em></h1><p>安排连接与画幅，确认费用，让每一条创作有据可查。</p><RouterLink to="/video">前往视频创作 ↗</RouterLink></div><div class="qva-reel" aria-hidden="true"><i>▶</i><b>MAKE IT<br>MOVE.</b><span>Q / 24</span></div></header><div v-if="error" class="qva-error" role="alert">{{ error }}<button type="button" @click="load">重新读取</button></div><BrandLoader v-if="loading && !loaded" text="正在打开视频控制台…" />
    <template v-if="loaded"><section class="qva-overview"><article><small>01 / 创作连接</small><strong>{{ presets.filter(p => p.enabled).length }} 个已开启</strong><span>保存设置不会自动生成</span></article><article><small>02 / 等待成片</small><strong>{{ receipts.filter(t => videoActive(t.status)).length }} 条进行中</strong><span>已取得任务号后只续查原任务</span></article><article><small>03 / 费用纪律</small><strong>确认、预留、再结算</strong><span>未完成释放，过期权益按原规则处理</span></article></section>
    <section class="qva-panel"><header><div><span>THE CONNECTION DESK</span><h2>为片场安排一条连接</h2><p>复用现有加密渠道；视频参数按协议能力开放。</p></div><button type="button" class="qva-secondary" :disabled="saving" @click="add">＋ 添加创作连接</button></header><div class="qva-presets"><button v-for="p in presets" :key="p.id" type="button" :aria-pressed="selectedId === p.id" @click="edit(p)"><b>{{ p.name }}</b><small>{{ p.enabled ? '已开启' : '未开启' }}</small></button><span v-if="!presets.length">还没有视频连接，先添加一条。</span></div>
      <form v-if="draft" @submit.prevent="save"><div class="qva-form"><label>前台名称<input v-model="draft.name" aria-label="视频连接名称" maxlength="60" required /></label><label>视频协议<select v-model="draft.profile" aria-label="视频协议" @change="changedProfile"><option v-for="p in profiles" :key="p.key" :value="p.key">{{ p.name }}</option></select></label><label>已有加密渠道<select v-model="draft.channelId" aria-label="视频加密渠道"><option value="">暂未选择</option><option v-for="c in channels" :key="c.id" :value="c.id" :disabled="!c.enabled">{{ c.name }}{{ c.enabled ? '' : ' · 未开启' }}</option></select><small>密钥继续保存在渠道中，任务不会复制明文密钥。</small></label><label>上游模型或接入点<input v-model="draft.upstreamModel" aria-label="视频上游模型" maxlength="128" :placeholder="draft.profile === 'PIKA_1' ? '1.0' : '填写已开通的模型或接入点 ID'" /><small>能力档位应与已开通模型对应，真实可用性需要联调确认。</small></label><label>基础次数<input v-model.number="draft.baseCost" aria-label="视频基础次数" type="number" min="0" max="1000000" required /></label><label>每秒追加次数<input v-model.number="draft.perSecondCost" aria-label="视频每秒次数" type="number" min="0" max="1000000" required /><small>{{ draft.profile === 'FAL_UPSCALE' ? '整条报价 = 基础次数 + 向上取整（原片秒数 × 每秒次数 × 放大倍率²）。' : draft.profile === 'FAL_LIPSYNC' ? '整条报价 = 基础次数 + 向上取整（较长素材秒数 × 每秒次数）。' : '整条报价 = 基础次数 + 向上取整（请求秒数 × 每秒次数）。' }}</small></label><label>扣减次数池<select v-model="draft.pool" aria-label="视频次数池"><option v-for="(label,key) in videoPools" :key="key" :value="key">{{ label }}</option></select></label><label>最长等待（分钟）<input v-model.number="draft.maxWaitMinutes" aria-label="视频最长等待" type="number" min="2" max="120" required /></label><label class="qva-wide">本站公网入口<input v-model="draft.publicBaseUrl" aria-label="视频公网入口" placeholder="https://你的站点域名（素材供服务方临时读取）" maxlength="500" /><small>参考图、素材导演、视频改写、续写、精修与口型同步需要本站公网素材入口。只发放绑定本任务、会过期的私有读取凭证。</small></label></div><div class="qva-form-foot"><label><input v-model="draft.enabled" aria-label="开启视频连接" type="checkbox" />开启这条创作连接</label><div><span>版本 {{ draft.version }} · 保存不出网</span><button type="submit" class="qva-primary" :disabled="saving">{{ saving ? '保存中…' : '保存这条连接' }}</button></div></div></form><div v-else class="qva-empty">选择已有连接，或添加第一条创作连接。</div><p class="qva-note">Pika Web 对应第三方网关协议；方舟采用原生异步视频任务接口。保存设置只检查字段与版本，不发起生成或验证外部费用。</p></section>
    <section class="qva-panel"><header><div><span>EVERY TAKE HAS A RECEIPT</span><h2>创作回执</h2><p>状态、外部任务号与次数处理；参考素材和下载凭证不展示。</p></div><button type="button" class="qva-secondary" :disabled="refreshing" @click="loadReceipts">{{ refreshing ? '读取中…' : '刷新回执' }}</button></header><div v-if="receiptError" class="qva-error" role="alert">{{ receiptError }}</div><div v-else-if="!receipts.length" class="qva-empty">片场还很安静。第一条创作开始后，回执会出现在这里。</div><div v-else class="qva-receipts"><article v-for="t in receipts" :key="t.id"><div class="qva-receipt-icon">▶</div><div class="qva-receipt-copy"><strong>{{ t.presetName }} <small>{{ t.modeLabel }}</small></strong><p>{{ t.prompt }}</p><span>{{ videoStatus(t.status) }} · {{ date(t.createdAt) }}</span><small v-if="t.upstreamId">外部任务 {{ t.upstreamId }}</small><small v-if="t.message">{{ t.message }}</small></div><div class="qva-receipt-bill"><b>结算 {{ t.billing.charged }} 次</b><span>预留 {{ t.billing.reserved }} · 释放 {{ t.billing.returned }}</span><small v-if="t.billing.expired">到期失效 {{ t.billing.expired }}</small><button v-if="['POLLING','SAVING','SETTLING'].includes(t.status)" type="button" :disabled="checking.has(t.id)" @click="checkAgain(t)">{{ checking.has(t.id) ? '安排中…' : '再查一次' }}</button></div></article></div></section></template>
  </main>
</template>

<script setup>
import { onMounted, onUnmounted, reactive, ref, watch } from 'vue';
import { RouterLink } from 'vue-router';
import { ElMessage } from 'element-plus';
import { api } from '../../api/client.js';
import { useAuth } from '../../stores/auth.js';
import { videoActive, videoPools, videoStatus } from '../../lib/video-intent.js';
import BrandLoader from '../../components/design/BrandLoader.vue';
import '../../components/design/video-control.css';
const auth = useAuth(), owner = auth.user?.id, presets = ref([]), channels = ref([]), profiles = ref([]), receipts = ref([]), selectedId = ref(''), draft = ref(null), error = ref(''), receiptError = ref(''), loading = ref(false), loaded = ref(false), saving = ref(false), refreshing = ref(false), checking = reactive(new Set());
let alive = true; const requests = new Map(), current = () => alive && auth.isAdmin && auth.user?.id === owner;
function scope(key) { requests.get(key)?.abort(); const c = new AbortController(); requests.set(key, c); return { signal: c.signal, current: () => current() && !c.signal.aborted && requests.get(key) === c }; }
function edit(value) { selectedId.value = value.id; draft.value = JSON.parse(JSON.stringify(value)); }
function add() { selectedId.value = ''; draft.value = { name: '新的创作连接', profile: 'ARK_2_5', channelId: '', upstreamModel: '', baseCost: 0, perSecondCost: 0, pool: 'drawMj', maxWaitMinutes: 30, publicBaseUrl: '', enabled: false, version: 0 }; }
function changedProfile() { if (!draft.value) return; draft.value.upstreamModel = draft.value.profile === 'PIKA_1' ? '1.0' : ({FAL_UPSCALE:'topaz/upscale/video/precision',FAL_LIPSYNC:'fal-ai/sync-lipsync/v3'})[draft.value.profile] || ''; draft.value.publicBaseUrl = ''; }
async function load() { const req = scope('config'); loading.value = true; error.value = ''; try { const data = await api.get('/video/admin/config', { signal: req.signal }); if (!req.current()) return; presets.value = data.presets || []; channels.value = data.channels || []; profiles.value = data.profiles || []; loaded.value = true; const selected = presets.value.find(p => p.id === selectedId.value) || presets.value[0]; if (selected) edit(selected); else draft.value = null; await loadReceipts(); } catch (e) { if (req.current()) error.value = e.message || '视频配置暂未读取'; } finally { if (req.current()) loading.value = false; } }
async function save() { if (!draft.value || saving.value) return; const req = scope('save'); saving.value = true; error.value = ''; const value = { ...draft.value }; delete value.id; delete value.updatedAt; try { const saved = selectedId.value ? await api.put('/video/admin/presets/' + selectedId.value, value, { signal: req.signal }) : await api.post('/video/admin/presets', value, { signal: req.signal }); if (!req.current()) return; const index = presets.value.findIndex(p => p.id === saved.id); if (index < 0) presets.value.push(saved); else presets.value[index] = saved; edit(saved); ElMessage.success('视频连接已保存；没有发起生成。'); } catch (e) { if (req.current()) error.value = e.status === 409 ? '这条连接已被其他操作更新，请重新读取后编辑。' : e.message; } finally { if (req.current()) saving.value = false; } }
async function loadReceipts() { const req = scope('receipts'); refreshing.value = true; receiptError.value = ''; try { const rows = await api.get('/video/admin/receipts', { signal: req.signal }); if (req.current()) receipts.value = rows.items || []; } catch (e) { if (req.current()) receiptError.value = e.message || '回执暂未读取'; } finally { if (req.current()) refreshing.value = false; } }
async function checkAgain(task) { if (checking.has(task.id)) return; checking.add(task.id); try { await api.post('/video/admin/tasks/' + task.id + '/check'); if (current()) { ElMessage.success('已安排核对原任务，不重新提交生成。'); await loadReceipts(); } } catch (e) { if (current()) receiptError.value = e.message; } finally { if (current()) checking.delete(task.id); } }
const date = value => value ? new Date(value).toLocaleString('zh-CN', { hour12: false }) : '';
function close() { alive = false; for (const c of requests.values()) c.abort(); draft.value = null; receipts.value = []; }
watch(() => auth.user?.id, id => { if (id !== owner) close(); }); onMounted(load); onUnmounted(close);
</script>
